<?php

declare(strict_types=1);

if (! function_exists('timb_manifest')) {
    /**
     * The image set: dimensions and titles, keyed by image key.
     *
     * app/Data/ImageManifest.php is generated by tools/optimize_images.py and
     * is the fallback. Rows from the media library are merged over it, so an
     * image uploaded through the CMS is usable straight away, and a title
     * edited there takes effect without regenerating the file.
     */
    function timb_manifest(): array
    {
        static $manifest = null;

        if ($manifest !== null) {
            return $manifest;
        }

        $file = require APPPATH . 'Data/ImageManifest.php';

        try {
            $stored = App\Models\MediaModel::manifestRows();
        } catch (\Throwable $e) {
            log_message('error', 'Media library unavailable, using the generated manifest: ' . $e->getMessage());
            $stored = [];
        }

        return $manifest = $stored === [] ? $file : $stored + $file;
    }
}

if (! function_exists('img_url')) {
    function img_url(string $key, string $size = '640'): string
    {
        return base_url("assets/img/machines/{$key}-{$size}.webp");
    }
}

if (! function_exists('img_tag')) {
    /** <img> with intrinsic width/height (prevents layout shift). $attrs are escaped. */
    function img_tag(string $key, string $size, string $alt, array $attrs = []): string
    {
        if ($key === '') {
            return ''; // no photo set for this item — not an error
        }

        $dims = timb_manifest()[$key]['files'][$size] ?? null;
        if ($dims === null) {
            log_message('error', "Unknown image key: {$key} ({$size})");

            return '';
        }

        $attrs = ['src' => img_url($key, $size), 'alt' => $alt, 'width' => $dims[0], 'height' => $dims[1], 'decoding' => 'async'] + $attrs;
        $html  = '';
        foreach ($attrs as $name => $value) {
            $html .= ' ' . $name . '="' . esc((string) $value, 'attr') . '"';
        }

        return '<img' . $html . '>';
    }
}

if (! function_exists('timb_path')) {
    /**
     * The requested path with a leading slash, the front controller removed
     * and no query string: /about, never /index.php/about.
     *
     * Whether index.php appears depends on how the server rewrites URLs, so
     * anything comparing the path against stored data has to strip it.
     */
    function timb_path(?string $path = null): string
    {
        $path ??= current_url(true)->getPath();
        $path = ltrim((string) $path, '/');

        if ($path === 'index.php' || str_starts_with($path, 'index.php/')) {
            $path = ltrim(substr($path, strlen('index.php')), '/');
        }

        return '/' . $path;
    }
}

if (! function_exists('asset_url')) {
    /** Public asset URL with ?v=<mtime> cache-busting. */
    function asset_url(string $path): string
    {
        $file = FCPATH . ltrim($path, '/');

        return base_url($path) . (is_file($file) ? '?v=' . filemtime($file) : '');
    }
}

if (! function_exists('india_xy')) {
    /**
     * Lat/lon -> [x%, y%] inside the India map SVG (see partials/india_map.php).
     * Map bounds: lon 68.0–97.6, lat 6.5–37.3.
     */
    function india_xy(float $lat, float $lon): array
    {
        return [round(($lon - 68.0) / 29.6 * 100, 2), round((37.3 - $lat) / 30.8 * 100, 2)];
    }
}
